func newComponentConfig(main *Main, addr stackaddrs.ConfigComponent, stack *StackConfig, config *stackconfig.Component) *ComponentConfig {
	return &ComponentConfig{
		addr:   addr,
		stack:  stack,
		config: config,
		main:   main,
	}
